import{_ as a,c as t,a2 as i,o}from"./chunks/framework.CoXjB5sU.js";const p=JSON.parse('{"title":"Validate the domain ownership","description":"","frontmatter":{"prev":{"text":"Purchase a certificate from a CA","link":"/doc/guides/other-operations/replace-https-certificate/purchase-new-ca-certificate"},"next":{"text":"Undo a certificate replacement","link":"/doc/guides/other-operations/replace-https-certificate/undo-certificate-replacement"}},"headers":[],"relativePath":"doc/guides/other-operations/replace-https-certificate/validate-domain-owner.md","filePath":"doc/guides/other-operations/replace-https-certificate/validate-domain-owner.md"}'),r={name:"doc/guides/other-operations/replace-https-certificate/validate-domain-owner.md"};function n(d,e,s,l,h,c){return o(),t("div",null,e[0]||(e[0]=[i('<h1 id="validate-the-domain-ownership" tabindex="-1">Validate the domain ownership <a class="header-anchor" href="#validate-the-domain-ownership" aria-label="Permalink to &quot;Validate the domain ownership&quot;">​</a></h1><p>CAs offer several ways to prove that you control the domain of the certificate. Check with your CA which ones it supports.</p><h2 id="email-validation" tabindex="-1">Email validation <a class="header-anchor" href="#email-validation" aria-label="Permalink to &quot;Email validation&quot;">​</a></h2><p>The CA sends an email with a validation link to an administrative address of the domain, such as <em>admin@</em>, <em>administrator@</em>, <em>hostmaster@</em>, <em>postmaster@</em> or <em>webmaster@</em> followed by the domain name. Choose an address you can read, or ask your IT team to forward the message, and open the link.</p><h2 id="dns-validation" tabindex="-1">DNS validation <a class="header-anchor" href="#dns-validation" aria-label="Permalink to &quot;DNS validation&quot;">​</a></h2><p>The CA gives you a DNS record (usually a <em>CNAME</em> or <em>TXT</em> record) to add to the domain. Ask the team that manages your DNS to add it. The CA checks it after a few minutes, and you can remove the record once the certificate is issued.</p><h2 id="file-http-validation" tabindex="-1">File (HTTP) validation <a class="header-anchor" href="#file-http-validation" aria-label="Permalink to &quot;File (HTTP) validation&quot;">​</a></h2><p>The CA gives you a file to publish at <code>http://&lt;hostname&gt;/.well-known/pki-validation/&lt;file name&gt;</code>. The ioChem-BD proxy redirects every request to the Browse module, so this method needs a change in the proxy configuration. Prefer email or DNS validation; if file validation is the only option, contact us at <a href="mailto:contact@iochem-bd.org" target="_blank" rel="noreferrer">contact@iochem-bd.org</a>.</p>',8)]))}const f=a(r,[["render",n]]);export{p as __pageData,f as default};
